import {
  onAuthStateChanged,
  type User,
  OAuthProvider,
  signInWithPopup,
  signInWithEmailAndPassword,
} from 'firebase/auth'
import {
  collection,
  deleteDoc,
  doc,
  getDoc,
  getDocs,
  orderBy,
  query,
  setDoc,
  where,
} from 'firebase/firestore'
import { municipiosBrutos } from '#municipios'
import { deepSignal } from '../../cefiti/src/deep-signals.ts'
import { auth, db } from './firebase.ts'
import { diffLines } from 'diff'

export type AdminView =
  | 'login'
  | 'select_environment'
  | 'dashboard'
  | 'pragas'
  | 'hospedeiros'
  | 'legislacoes'
  | 'rules'
  | 'status_municipios'
  | 'catalogos'
  | 'usuarios'
  | 'perfil'
  | 'diff'

export interface AuthorizedUser {
  email: string
  nome: string
  cargo: string
  lotacao: string
  perfil: 'administrador' | 'usuário'
}

export interface Praga {
  prag: string
  pragc: string
  hosp: number[]
  files: string[]
}

export interface Hospedeiro {
  id: number
  nomeSci: string
  nomeVul: string[]
}

export interface Legislacao {
  id: string
  leg: string
  data: string
  texto?: string
}

export interface Rule {
  id?: string
  prag: string
  desc: string
  part: string[]
  status_origem: string[]
  status_destino: string[]
  exig: string[]
  leg: string
}

export interface Estado {
  ibge: number
  UF: string
  estado: string
}

export interface Municipio {
  id: string
  nome: string
  uf: string
  code: number
}

export interface DB_StatusMunicipio {
  id?: string
  praga: string
  status: {
    status_fitossanitário: string
    estados: {
      uf: string
      ibge: number
      municipios: Record<string, string>
    }[]
  }[]
}

export class Store {
  view: AdminView = 'login' //'dashboard'
  user: User | null = null
  currentProfile: AuthorizedUser | null = null
  authLoading: boolean = true
  sidebarOpen: boolean = true

  // Environment isolated state
  environment: 'producao' | 'desenvolvimento' | null = null
  prodVersion: number = 0
  devVersion: number = 0
  prodLastUpdate: string | null = null
  devLastUpdate: string | null = null
  loadingVersions: boolean = false
  diffLinesResult: { added?: boolean; removed?: boolean; value: string }[] = []
  loadingDiff: boolean = false
  loadingDbAction: boolean = false
  loadingDbActionMessage: string = ''

  get isReadOnly() {
    return this.environment === 'producao'
  }

  envCol(name: string) {
    if (!this.environment) throw new Error('Ambiente não selecionado')
    return collection(db, this.environment, 'dados', name)
  }

  envDoc(name: string, id: string) {
    if (!this.environment) throw new Error('Ambiente não selecionado')
    return doc(db, this.environment, 'dados', name, id)
  }

  geodataCol(name: string) {
    return collection(db, 'geodata', 'dados', name)
  }

  geodataDoc(name: string, id: string) {
    return doc(db, 'geodata', 'dados', name, id)
  }

  // Collections
  pragas: Praga[] = []
  hospedeiros: Hospedeiro[] = []
  legislacoes: Legislacao[] = []
  rules: Rule[] = []
  estados: Estado[] = []
  status_municipios: DB_StatusMunicipio[] = []
  authorized_users: AuthorizedUser[] = []
  catalogos = {
    status_fitossanitario: [] as string[],
    dbVersion: 0,
    lastUpdate: null as string | null,
  }

  loading = {
    pragas: false,
    hospedeiros: false,
    legislacoes: false,
    rules: false,
    estados: false,
    status_municipios: false,
    catalogos: false,
    authorized_users: false,
  }

  // UI State for Views
  views = {
    pragas: {
      editing: null as Praga | null,
      isNew: false,
      selectedLegId: '',
      selectedHospId: '',
    },
    hospedeiros: {
      editing: null as Hospedeiro | null,
      isNew: false,
      vulInput: '',
    },
    legislacoes: {
      editing: null as Legislacao | null,
      isNew: false,
      showPreview: false,
      texto: '',
    },
    rules: {
      editing: null as Rule | null,
      isNew: false,
    },
    statusMunicipios: {
      selectedPraga: '',
      selectedStatus: '',
      selectedUF: '',
      currentEntry: null as DB_StatusMunicipio | null,
      originalEntryJson: '',
      municipios: [] as Municipio[],
      selectedInStatus: [] as string[],
      selectedInAvailable: [] as string[],
      showAddStatus: false,
      showAddEstado: false,
    },
    catalogos: {
      newStatus: '',
    },
    usuarios: {
      editing: null as AuthorizedUser | null,
      isNew: false,
    },
    perfil: {
      editing: null as AuthorizedUser | null,
    },
  }

  //constructor() {}

  initAuth() {
    console.log('[Store] Initing Auth listener...')
    onAuthStateChanged(auth, async (user) => {
      console.log('[Store] Auth State Changed:', user ? user.email : 'No user')
      this.user = user

      try {
        if (!user) {
          this.currentProfile = null
          this.view = 'login'
          this.environment = null
        } else {
          console.log('[Store] Fetching profile for:', user.email)
          await this.fetchProfile()
          console.log('[Store] Profile loaded:', this.currentProfile?.perfil)

          if (this.view === 'login' || this.view === 'dashboard') {
            this.view = 'select_environment'
            await this.fetchEnvironmentsInfo()
          } else if (this.environment) {
            this.fetchCatalogos()
          }
        }
      } catch (e) {
        console.error('[Store] Auth error:', e)
        this.view = 'login'
        // Only alert if there was a real user but profile fetch failed
        if (user) {
          alert(
            'Acesso negado: seu e-mail não está cadastrado ou houve erro no sistema.',
          )
          await this.logout()
        }
      } finally {
        this.authLoading = false
        console.log('[Store] Auth initialization complete. View:', this.view)
      }
    })
  }

  async fetchEnvironmentsInfo() {
    this.loadingVersions = true
    try {
      const prodSnap = await getDoc(doc(db, 'producao', 'versao'))
      if (prodSnap.exists()) {
        const d = prodSnap.data()
        this.prodVersion = d.version || 0
        this.prodLastUpdate = d.lastUpdate
          ? new Date(
              d.lastUpdate.seconds ? d.lastUpdate.seconds * 1000 : d.lastUpdate,
            ).toLocaleDateString()
          : null
      }
      const devSnap = await getDoc(doc(db, 'desenvolvimento', 'versao'))
      if (devSnap.exists()) {
        const d = devSnap.data()
        this.devVersion = d.version || 0
        this.devLastUpdate = d.lastUpdate
          ? new Date(
              d.lastUpdate.seconds ? d.lastUpdate.seconds * 1000 : d.lastUpdate,
            ).toLocaleDateString()
          : null
      }
    } catch (e) {
      console.error('Error fetching environments info:', e)
    } finally {
      this.loadingVersions = false
    }
  }

  async selectEnvironment(env: 'producao' | 'desenvolvimento') {
    this.environment = env
    this.view = 'dashboard'
    await this.fetchCatalogos()
  }

  async fetchProfile() {
    if (!this.user?.email) return
    try {
      const docRef = doc(
        db,
        'configuracoes',
        'geral',
        'usuarios',
        this.user.email.toLowerCase(),
      )
      const snap = await getDoc(docRef)
      if (snap.exists()) {
        this.currentProfile = snap.data() as AuthorizedUser
      } else {
        console.warn('[Store] Profile not found for:', this.user.email)
        throw new Error('Não autorizado')
      }
    } catch (e) {
      console.error('[Store] Error fetching profile:', e)
      throw e
    }
  }

  async loginWithMicrosoft() {
    const provider = new OAuthProvider('microsoft.com')
    // Adicione escopos se necessário para obter mais infos, mas o Firebase lida com o básico
    try {
      await signInWithPopup(auth, provider)
    } catch (error) {
      console.error('Erro no login Microsoft:', error)
      alert(
        'Erro ao entrar com Microsoft. Verifique se o pop-up foi bloqueado.',
      )
    }
  }

  async loginWithPassword(email: string, pass: string) {
    if (email === 'cefiti@agro.gov.br' && pass === 'cefiti-admin1357') {
      try {
        await signInWithEmailAndPassword(auth, email, pass)
      } catch (error: any) {
        console.error(
          'Password login failed, attempting fallback signup:',
          error,
        )
        if (
          error.code === 'auth/user-not-found' ||
          error.code === 'auth/invalid-credential'
        ) {
          /* try {
            await createUserWithEmailAndPassword(auth, email, pass)
            console.log('Successfully created test user in Firebase Auth.')
          } catch (signUpError: any) {
          console.error('Signup fallback failed:', signUpError)
          throw new Error(
            `Falha no cadastro de teste (${signUpError.code}): ${signUpError.message}`,
          )
          } */
        } else {
          throw new Error(
            `Falha no login de teste (${error.code}): ${error.message}`,
          )
        }
      }
    } else {
      throw new Error('Usuário ou senha inválidos (credenciais incorretas).')
    }
  }

  async setView(view: AdminView) {
    this.view = view
    if (view === 'select_environment') {
      await this.fetchEnvironmentsInfo()
      return
    }

    if (
      !this.environment &&
      view !== 'login' &&
      view !== 'perfil' &&
      view !== 'usuarios'
    ) {
      this.view = 'select_environment'
      await this.fetchEnvironmentsInfo()
      return
    }

    switch (view) {
      case 'pragas':
        await Promise.all([
          this.fetchPragas(),
          this.fetchHospedeiros(),
          this.fetchLegislacoes(),
        ])
        break
      case 'hospedeiros':
        await this.fetchHospedeiros()
        break
      case 'legislacoes':
        await this.fetchLegislacoes()
        break
      case 'rules':
        await Promise.all([
          this.fetchRules(),
          this.fetchPragas(),
          this.fetchLegislacoes(),
          this.fetchCatalogos(),
        ])
        break
      case 'status_municipios':
        await Promise.all([
          this.initStatusMunicipiosView(),
          this.fetchCatalogos(),
        ])
        break
      case 'catalogos':
        await this.fetchCatalogos()
        break
      case 'usuarios':
        await this.fetchAuthorizedUsers()
        break
      case 'perfil':
        if (this.currentProfile) {
          this.views.perfil.editing = { ...this.currentProfile }
        }
        break
      case 'diff':
        await this.fetchAndDiff()
        break
    }
  }

  toggleSidebar() {
    this.sidebarOpen = !this.sidebarOpen
  }

  async logout() {
    await auth.signOut()
    this.environment = null
    this.view = 'login'
  }

  // --- Data Methods ---

  async fetchPragas() {
    this.loading.pragas = true
    try {
      const q = query(this.envCol('pragas'), orderBy('prag'))
      const snapshot = await getDocs(q)
      this.pragas = snapshot.docs.map((doc) => doc.data() as Praga)
    } catch (e) {
      console.error('[Store] Error fetching pragas:', e)
    } finally {
      this.loading.pragas = false
    }
  }

  async savePraga(praga: Praga) {
    if (this.isReadOnly) throw new Error('Apenas visualização em produção')
    await setDoc(this.envDoc('pragas', praga.prag), praga)
    await this.fetchPragas()
  }

  async deletePraga(prag: string) {
    if (this.isReadOnly) throw new Error('Apenas visualização em produção')
    await deleteDoc(this.envDoc('pragas', prag))
    await this.fetchPragas()
  }

  async fetchHospedeiros() {
    this.loading.hospedeiros = true
    try {
      const q = query(this.envCol('hospedeiros'), orderBy('nomeSci'))
      const snapshot = await getDocs(q)
      this.hospedeiros = snapshot.docs.map((doc) => doc.data() as Hospedeiro)
    } catch (e) {
      console.error('[Store] Error fetching hospedeiros:', e)
    } finally {
      this.loading.hospedeiros = false
    }
  }

  async saveHospedeiro(h: Hospedeiro) {
    if (this.isReadOnly) throw new Error('Apenas visualização em produção')
    await setDoc(this.envDoc('hospedeiros', h.id.toString()), h)
    await this.fetchHospedeiros()
  }

  async deleteHospedeiro(id: number) {
    if (this.isReadOnly) throw new Error('Apenas visualização em produção')
    await deleteDoc(this.envDoc('hospedeiros', id.toString()))
    await this.fetchHospedeiros()
  }

  async fetchLegislacoes() {
    this.loading.legislacoes = true
    try {
      const q = query(this.envCol('legislacoes'), orderBy('id', 'desc'))
      const snapshot = await getDocs(q)
      this.legislacoes = snapshot.docs.map((doc) => doc.data() as Legislacao)
    } catch (e) {
      console.error('[Store] Error fetching legislacoes:', e)
    } finally {
      this.loading.legislacoes = false
    }
  }

  async getLegislacaoTexto(id: string) {
    const leg = this.legislacoes.find((l) => l.id === id)
    return leg?.texto || ''
  }

  async saveLegislacao(l: Legislacao, texto: string) {
    if (this.isReadOnly) throw new Error('Apenas visualização em produção')
    const updated = { ...l, texto }
    await setDoc(this.envDoc('legislacoes', updated.id), updated)
    await this.fetchLegislacoes()
  }

  async deleteLegislacao(id: string) {
    if (this.isReadOnly) throw new Error('Apenas visualização em produção')
    await deleteDoc(this.envDoc('legislacoes', id))
    await this.fetchLegislacoes()
  }

  async fetchRules() {
    this.loading.rules = true
    try {
      const q = query(this.envCol('rules'), orderBy('prag'))
      const snapshot = await getDocs(q)
      this.rules = snapshot.docs.map((d) => ({ ...d.data(), id: d.id }) as Rule)
    } catch (e) {
      console.error('[Store] Error fetching rules:', e)
    } finally {
      this.loading.rules = false
    }
  }

  async saveRule(rule: Rule) {
    if (this.isReadOnly) throw new Error('Apenas visualização em produção')
    const docId = rule.id || `${rule.prag}_${Date.now()}`
    const { id, ...data } = rule
    await setDoc(this.envDoc('rules', docId), data)
    await this.fetchRules()
  }

  async deleteRule(id: string) {
    if (this.isReadOnly) throw new Error('Apenas visualização em produção')
    await deleteDoc(this.envDoc('rules', id))
    await this.fetchRules()
  }

  async fetchEstados() {
    this.loading.estados = true
    try {
      const snapshot = await getDocs(this.geodataCol('estados'))
      this.estados = snapshot.docs
        .map((d) => d.data() as Estado)
        .sort((a, b) => a.estado.localeCompare(b.estado))
    } finally {
      this.loading.estados = false
    }
  }

  async fetchStatusMunicipios() {
    this.loading.status_municipios = true
    try {
      const snapshot = await getDocs(this.envCol('status_municipio'))
      this.status_municipios = snapshot.docs.map(
        (d) => ({ ...d.data(), id: d.id }) as DB_StatusMunicipio,
      )
    } finally {
      this.loading.status_municipios = false
    }
  }

  async saveStatusMunicipio(entry: DB_StatusMunicipio) {
    if (this.isReadOnly) throw new Error('Apenas visualização em produção')
    const id = entry.id || entry.praga.replace(/\s+/g, '_')
    const { id: _, ...data } = entry
    await setDoc(this.envDoc('status_municipio', id), data)
    this.views.statusMunicipios.originalEntryJson = JSON.stringify(entry)
    await this.fetchStatusMunicipios()
  }

  async initStatusMunicipiosView() {
    await Promise.all([
      this.fetchPragas(),
      this.fetchEstados(),
      this.fetchStatusMunicipios(),
    ])

    // Parse Municipios
    const ufMap = new Map<string, string>()
    this.estados.forEach((e) => {
      ufMap.set(String(e.ibge), e.UF)
    })

    this.views.statusMunicipios.municipios = municipiosBrutos.map((m) => {
      const id = m.slice(0, 6)
      const nome = m.slice(6).trim()
      const ibgePrefix = id.slice(0, 2)
      const uf = ufMap.get(ibgePrefix) || ''
      return { id, nome, uf, code: Number(id.slice(2)) }
    })
  }

  updateStatusMunicipiosEntry() {
    const praga = this.views.statusMunicipios.selectedPraga
    if (!praga) {
      this.views.statusMunicipios.currentEntry = null
      return
    }

    const found = this.status_municipios.find((d) => d.praga === praga)
    if (found) {
      this.views.statusMunicipios.currentEntry = JSON.parse(
        JSON.stringify(found),
      )
    } else {
      this.views.statusMunicipios.currentEntry = { praga, status: [] }
    }
    this.views.statusMunicipios.originalEntryJson = JSON.stringify(
      this.views.statusMunicipios.currentEntry,
    )
  }

  async fetchCatalogos() {
    this.loading.catalogos = true
    try {
      // Fetch status list (global)
      const catRef = doc(db, 'configuracoes', 'catalogos')
      const catSnap = await getDoc(catRef)
      if (catSnap.exists()) {
        const data = catSnap.data()
        this.catalogos.status_fitossanitario = data.status_fitossanitario || []
      }

      // Fetch version and last update info (environment specific)
      if (this.environment) {
        const geralRef = doc(db, this.environment, 'versao')
        const geralSnap = await getDoc(geralRef)
        if (geralSnap.exists()) {
          const data = geralSnap.data()
          this.catalogos.dbVersion = data.version || 0
          this.catalogos.lastUpdate = data.lastUpdate
            ? new Date(
                data.lastUpdate.seconds
                  ? data.lastUpdate.seconds * 1000
                  : data.lastUpdate,
              ).toLocaleDateString()
            : null
        }
      }
    } finally {
      this.loading.catalogos = false
    }
  }

  async checkStatusInUse(
    s: string,
  ): Promise<{ inUse: boolean; locations: string[] }> {
    const locations: string[] = []

    try {
      // 1. Check in Rules (Origem)
      const qOrigem = query(
        this.envCol('rules'),
        where('status_origem', 'array-contains', s),
      )
      const snapOrigem = await getDocs(qOrigem)
      if (!snapOrigem.empty) {
        locations.push(
          ...snapOrigem.docs.map(
            (d) =>
              `Regra (Praga: ${d.data().prag}): ${d.data().desc || d.id} (NA ORIGEM)`,
          ),
        )
      }

      // 2. Check in Rules (Destino)
      const qDestino = query(
        this.envCol('rules'),
        where('status_destino', 'array-contains', s),
      )
      const snapDestino = await getDocs(qDestino)
      if (!snapDestino.empty) {
        locations.push(
          ...snapDestino.docs.map(
            (d) =>
              `Regra (Praga: ${d.data().prag}): ${d.data().desc || d.id} (NO DESTINO)`,
          ),
        )
      }

      // 3. Check in Status Município
      // We list and check in-memory since Firestore doesn't support array-contains for nested object fields
      const qMun = this.envCol('status_municipio')
      const snapMun = await getDocs(qMun)
      snapMun.docs.forEach((doc) => {
        const data = doc.data() as DB_StatusMunicipio
        if (data.status?.some((st) => st.status_fitossanitário === s)) {
          locations.push(`Status Município: ${data.praga}`)
        }
      })
    } catch (e) {
      console.error('[Store] Error checking status usage:', e)
    }

    return {
      inUse: locations.length > 0,
      locations,
    }
  }

  async saveCatalogos(updatedStatuses: string[]) {
    if (this.isReadOnly) throw new Error('Apenas visualização em produção')
    const docRef = doc(db, 'configuracoes', 'catalogos')
    await setDoc(
      docRef,
      {
        status_fitossanitario: updatedStatuses,
      },
      { merge: true },
    )
    await this.fetchCatalogos()
  }

  async promoteDevToProd() {
    if (this.currentProfile?.perfil !== 'administrador') {
      alert('Apenas administradores podem promover a base.')
      return
    }
    if (
      !confirm(
        'Tem certeza de que deseja promover a base de DESENVOLVIMENTO para PRODUÇÃO? Isso substituirá todos os dados em produção.',
      )
    ) {
      return
    }

    this.loadingDbAction = true
    this.loadingDbActionMessage =
      'Publicando versão (Promovendo DESENVOLVIMENTO para PRODUÇÃO)...'
    this.loading.catalogos = true // block UI
    try {
      // 1. Fetch current production version and data
      const prodVersaoRef = doc(db, 'producao', 'versao')
      const prodVersaoSnap = await getDoc(prodVersaoRef)
      const currentProdVersion = prodVersaoSnap.exists()
        ? prodVersaoSnap.data()?.version || 0
        : 0

      const collections = [
        'pragas',
        'hospedeiros',
        'legislacoes',
        'rules',
        'status_municipio',
      ]

      const prodData: Record<string, any[]> = {}
      for (const col of collections) {
        const snap = await getDocs(collection(db, 'producao', 'dados', col))
        prodData[col] = snap.docs.map((d) => d.data())
      }

      // 2. Archive production database
      console.log(`Archiving production version ${currentProdVersion}...`)
      const archiveRef = doc(
        db,
        'archive',
        `v${currentProdVersion}_${Date.now()}`,
      )
      await setDoc(archiveRef, {
        version: currentProdVersion,
        timestamp: new Date(),
        data: prodData,
      })

      // 3. Fetch all development data
      console.log('Fetching development data...')
      const devData: Record<string, any[]> = {}
      for (const col of collections) {
        const snap = await getDocs(
          collection(db, 'desenvolvimento', 'dados', col),
        )
        devData[col] = snap.docs.map((d) => d.data())
      }

      // 4. Copy development to production
      console.log('Copying development to production...')
      for (const col of collections) {
        // Delete all production documents
        const prodColSnap = await getDocs(
          collection(db, 'producao', 'dados', col),
        )
        for (const docSnap of prodColSnap.docs) {
          await deleteDoc(doc(db, 'producao', 'dados', col, docSnap.id))
        }

        // Write development documents to production
        for (const item of devData[col]) {
          let docId = ''
          if (col === 'pragas') docId = item.prag
          else if (col === 'hospedeiros') docId = item.id.toString()
          else if (col === 'legislacoes') docId = item.id
          else if (col === 'rules')
            docId = item.id || `${item.prag}_${Date.now()}`
          else if (col === 'status_municipio')
            docId = item.id || item.praga.replace(/\s+/g, '_')

          const { id, ...data } = item
          await setDoc(doc(db, 'producao', 'dados', col, docId), {
            ...data,
            ...(id ? { id } : {}),
          })
        }
      }

      // 5. Update production version to V_dev (prodVersion + 1)
      const nextProdVersion = currentProdVersion + 1
      await setDoc(prodVersaoRef, {
        version: nextProdVersion,
        lastUpdate: new Date(),
      })

      // 6. Increment development version to V_dev + 1
      const nextDevVersion = nextProdVersion + 1
      await setDoc(doc(db, 'desenvolvimento', 'versao'), {
        version: nextDevVersion,
        lastUpdate: new Date(),
      })

      alert('Base promovida com sucesso! Produção atualizada.')
      await this.fetchEnvironmentsInfo()
      await this.fetchCatalogos()
    } catch (e) {
      console.error('Error promoting dev to prod:', e)
      alert(`Erro ao promover base: ${(e as Error).message}`)
    } finally {
      this.loading.catalogos = false
      this.loadingDbAction = false
      this.loadingDbActionMessage = ''
    }
  }

  async restoreDevFromProd() {
    if (this.currentProfile?.perfil !== 'administrador') {
      alert('Apenas administradores podem restaurar a base.')
      return
    }
    if (
      !confirm(
        'ATENÇÃO: Isso apagará TODOS os dados do ambiente de DESENVOLVIMENTO e os substituirá pela base de PRODUÇÃO atual. Deseja prosseguir?',
      )
    ) {
      return
    }

    this.loadingDbAction = true
    this.loadingDbActionMessage =
      'Descartando alterações e restaurando a partir de PRODUÇÃO...'
    this.loading.catalogos = true // block UI
    try {
      // 1. Fetch production version
      const prodVersaoRef = doc(db, 'producao', 'versao')
      const prodVersaoSnap = await getDoc(prodVersaoRef)
      const prodVersion = prodVersaoSnap.exists()
        ? prodVersaoSnap.data()?.version || 0
        : 0

      const collections = [
        'pragas',
        'hospedeiros',
        'legislacoes',
        'rules',
        'status_municipio',
      ]

      // 2. Fetch all production data
      console.log('Fetching production data...')
      const prodData: Record<string, any[]> = {}
      for (const col of collections) {
        const snap = await getDocs(collection(db, 'producao', 'dados', col))
        prodData[col] = snap.docs.map((d) => d.data())
      }

      // 3. Clear and copy to development
      console.log('Overwriting development with production...')
      for (const col of collections) {
        // Delete all dev documents
        const devColSnap = await getDocs(
          collection(db, 'desenvolvimento', 'dados', col),
        )
        for (const docSnap of devColSnap.docs) {
          await deleteDoc(doc(db, 'desenvolvimento', 'dados', col, docSnap.id))
        }

        // Write production documents to development
        for (const item of prodData[col]) {
          let docId = ''
          if (col === 'pragas') docId = item.prag
          else if (col === 'hospedeiros') docId = item.id.toString()
          else if (col === 'legislacoes') docId = item.id
          else if (col === 'rules')
            docId = item.id || `${item.prag}_${Date.now()}`
          else if (col === 'status_municipio')
            docId = item.id || item.praga.replace(/\s+/g, '_')

          const { id, ...data } = item
          await setDoc(doc(db, 'desenvolvimento', 'dados', col, docId), {
            ...data,
            ...(id ? { id } : {}),
          })
        }
      }

      // 4. Update dev version to prodVersion + 1
      const nextDevVersion = prodVersion + 1
      await setDoc(doc(db, 'desenvolvimento', 'versao'), {
        version: nextDevVersion,
        lastUpdate: new Date(),
      })

      alert('Base de desenvolvimento restaurada com sucesso.')
      await this.fetchEnvironmentsInfo()
      await this.fetchCatalogos()
    } catch (e) {
      console.error('Error restoring dev from prod:', e)
      alert(`Erro ao restaurar base: ${(e as Error).message}`)
    } finally {
      this.loading.catalogos = false
      this.loadingDbAction = false
      this.loadingDbActionMessage = ''
    }
  }

  // --- Authorized Users Methods ---

  async fetchAuthorizedUsers() {
    if (this.currentProfile?.perfil !== 'administrador') return
    this.loading.authorized_users = true
    try {
      const snapshot = await getDocs(
        collection(db, 'configuracoes', 'geral', 'usuarios'),
      )
      this.authorized_users = snapshot.docs.map(
        (doc) => doc.data() as AuthorizedUser,
      )
    } finally {
      this.loading.authorized_users = false
    }
  }

  async saveAuthorizedUser(user: AuthorizedUser) {
    const email = user.email.toLowerCase()
    await setDoc(doc(db, 'configuracoes', 'geral', 'usuarios', email), {
      ...user,
      email,
    })
    await this.fetchAuthorizedUsers()
    // Se estiver editando o próprio perfil, atualiza o currentProfile
    if (email === this.user?.email?.toLowerCase()) {
      this.currentProfile = { ...user, email }
    }
  }

  async deleteAuthorizedUser(email: string) {
    await deleteDoc(
      doc(db, 'configuracoes', 'geral', 'usuarios', email.toLowerCase()),
    )
    await this.fetchAuthorizedUsers()
  }

  // --- Diff & Export Methods ---

  async generateEnvironmentJson(
    env: 'desenvolvimento' | 'producao',
    stripTexto = false,
  ) {
    const collections = [
      'pragas',
      'hospedeiros',
      'legislacoes',
      'rules',
      'status_municipio',
    ]

    const data: Record<string, any[]> = {}
    let version: any = 'unknown'

    // Fetch version
    const configDoc = await getDoc(doc(db, env, 'versao'))
    if (configDoc.exists()) {
      version = configDoc.data()?.version || 0
    }

    // Fetch estados
    const estadosSnapshot = await getDocs(
      collection(db, 'geodata', 'dados', 'estados'),
    )
    data.estados = estadosSnapshot.docs
      .map((doc) => doc.data())
      .sort((a: any, b: any) => (a.estado || '').localeCompare(b.estado || ''))

    for (const collName of collections) {
      const snapshot = await getDocs(collection(db, env, 'dados', collName))
      let docs = snapshot.docs.map((doc) => doc.data())

      // Sort docs to make diff deterministic
      if (collName === 'pragas') {
        docs.sort((a: any, b: any) =>
          (a.prag || '').localeCompare(b.prag || ''),
        )
      } else if (collName === 'hospedeiros') {
        docs.sort((a: any, b: any) => (a.id || 0) - (b.id || 0))
      } else if (collName === 'legislacoes') {
        docs.sort((a: any, b: any) => (a.id || '').localeCompare(b.id || ''))
        if (stripTexto) {
          docs = docs.map((doc: any) => {
            const { texto, ...rest } = doc
            return rest
          })
        }
      } else if (collName === 'rules') {
        docs.sort((a: any, b: any) => {
          const pragComp = (a.prag || '').localeCompare(b.prag || '')
          if (pragComp !== 0) return pragComp
          return (a.desc || '').localeCompare(b.desc || '')
        })
      } else if (collName === 'status_municipio') {
        docs.sort((a: any, b: any) =>
          (a.praga || '').localeCompare(b.praga || ''),
        )
        docs = docs.map((doc: any) => {
          if (doc.status) {
            doc.status = doc.status.map((s: any) => {
              if (s.estados) {
                s.estados = s.estados.map((e: any) => {
                  if (e.municipios && !Array.isArray(e.municipios)) {
                    // Transform { "0090": "Amorinópolis" } -> [90]
                    e.municipios = Object.keys(e.municipios)
                      .map((key) => Number.parseInt(key, 10))
                      .filter((n) => !Number.isNaN(n))
                  }
                  if (Array.isArray(e.municipios)) {
                    e.municipios.sort((a: number, b: number) => a - b)
                  }
                  return e
                })
                s.estados.sort((a: any, b: any) =>
                  (a.uf || '').localeCompare(b.uf || ''),
                )
              }
              return s
            })
            doc.status.sort((a: any, b: any) =>
              (a.status_fitossanitário || '').localeCompare(
                b.status_fitossanitário || '',
              ),
            )
          }
          return doc
        })
      }

      data[collName === 'rules' ? 'regras' : collName] = docs
    }

    const finalJson = {
      dbVersion: version,
      ...data,
    }
    return this.sortObjectKeys(finalJson)
  }

  async fetchAndDiff() {
    this.loadingDiff = true
    this.diffLinesResult = []
    try {
      const prodJson = await this.generateEnvironmentJson('producao', false)
      const devJson = await this.generateEnvironmentJson(
        'desenvolvimento',
        false,
      )

      const prodStr = JSON.stringify(prodJson, null, 2)
      const devStr = JSON.stringify(devJson, null, 2)

      this.diffLinesResult = diffLines(prodStr, devStr)
    } catch (e) {
      console.error('Error generating diff:', e)
      alert('Erro ao carregar e gerar o diff.')
      this.view = 'catalogos'
    } finally {
      this.loadingDiff = false
    }
  }

  async downloadProductionDb() {
    try {
      this.loading.catalogos = true
      const prodJson = await this.generateEnvironmentJson('producao', true)
      const content = JSON.stringify(prodJson, null, 2)
      this.triggerDownload(content, 'db-next.json', 'application/json')
    } catch (e) {
      console.error('Error downloading production db:', e)
      alert('Erro ao baixar db-next.json de produção.')
    } finally {
      this.loading.catalogos = false
    }
  }

  async downloadProductionLegislacao() {
    try {
      this.loading.catalogos = true
      const snapshot = await getDocs(
        collection(db, 'producao', 'dados', 'legislacoes'),
      )
      const docs = snapshot.docs.map((doc) => doc.data())
      docs.sort((a: any, b: any) => (a.id || '').localeCompare(b.id || ''))

      const legTextoData = docs.map((doc: any) => ({
        id: doc.id || doc.legId,
        texto: doc.texto || '',
      }))

      let jsContent = '// CEFiTI - Legislacao\n\n'
      jsContent += `var leg_texto = ${JSON.stringify(legTextoData, null, 2)};\n`
      jsContent += `\nexport {\n  leg_texto\n};\n`

      this.triggerDownload(jsContent, 'legislacao.js', 'application/javascript')
    } catch (e) {
      console.error('Error downloading legislacoes:', e)
      alert('Erro ao baixar legislacao.js de produção.')
    } finally {
      this.loading.catalogos = false
    }
  }

  private triggerDownload(
    content: string,
    filename: string,
    contentType: string,
  ) {
    const blob = new Blob([content], { type: contentType })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = filename
    document.body.appendChild(a)
    a.click()
    document.body.removeChild(a)
    URL.revokeObjectURL(url)
  }

  private sortObjectKeys(obj: any): any {
    if (obj === null || typeof obj !== 'object') {
      return obj
    }
    if (Array.isArray(obj)) {
      return obj.map((item) => this.sortObjectKeys(item))
    }
    const sortedKeys = Object.keys(obj).sort()
    const sortedObj: Record<string, any> = {}
    for (const key of sortedKeys) {
      sortedObj[key] = this.sortObjectKeys(obj[key])
    }
    return sortedObj
  }
}

